(6455565, 958267, 40391, '<td valign="top">Inspired by Michelangelo.  Great find!</td>', 'Inspired by Michelangelo.  Great find!', '2011-06-29 04:20:29.000000', NULL, 1),
(6455566, 959138, 29777, '<td valign="top">I love the lighting on the snail. I wish it were bigger in the frame.</td>', 'I love the lighting on the snail. I wish it were bigger in the frame.', '2011-06-29 04:20:51.000000', NULL, 1),
(6455567, 958820, 40391, '<td valign="top">Mmmm a low key lighting strike  this actually works well.  Well done!</td>', 'Mmmm a low key lighting strike  this actually works well.  Well done!', '2011-06-29 04:21:18.000000', NULL, 1),
