(6455578, 959324, 40391, '<td valign="top">Nice capture but I would have title this Yin Yang Inverted</td>', 'Nice capture but I would have title this Yin Yang Inverted', '2011-06-29 04:46:24.000000', NULL, 1),
(6455588, 959111, 134946, '<td valign="top">Love this image.</td>', 'Love this image.', '2011-06-29 05:07:53.000000', NULL, 1),
