(6455736, 958645, 42495, '<td valign="top">I have no idea what this is, but I absolutely love it.</td>', 'I have no idea what this is, but I absolutely love it.', '2011-06-29 10:53:00.000000', NULL, 1),
(6455743, 958935, 42495, '<td valign="top">I really like this photo and especially the lighting.  What doesn''t work for me is the bear, it''s competing for attention with the boy, especially the brighter area on the head.</td>', 'I really like this photo and especially the lighting.  What doesn''t work for me is the bear, it''s competing for attention with the boy, especially the brighter area on the head.', '2011-06-29 11:04:58.000000', NULL, 1),
(6455744, 958737, 124346, '<td valign="top">Nice.</td>', 'Nice.', '2011-06-29 11:06:04.000000', NULL, 1),
(6455747, 958948, 42495, '<td valign="top">I''m not really seeing low key here.  I like the angle of the light; darken that background (low key) and turn down the light a bit and I think this would be a much stronger photo.  Just my opinion, of course.</td>', 'I''m not really seeing low key here.  I like the angle of the light; darken that background (low key) and turn down the light a bit and I think this would be a much stronger photo.  Just my opinion, of course.', '2011-06-29 11:08:52.000000', NULL, 1),
(6455754, 959176, 124346, '<td valign="top">It would be better if he was dropping a ball and take the picture just before it touched the ground.  I say this because of his pose.</td>', 'It would be better if he was dropping a ball and take the picture just before it touched the ground.  I say this because of his pose.', '2011-06-29 11:15:13.000000', NULL, 1),
(6455756, 959073, 124346, '<td valign="top">Nice one.  Makes you analyze it to discover what part of the body this is.  Love the detail in the skin texture.  I don''t know to much french but I think "derriere" means ass, right?</td>', 'Nice one.  Makes you analyze it to discover what part of the body this is.  Love the detail in the skin texture.  I don''t know to much french but I think "derriere" means ass, right?', '2011-06-29 11:18:42.000000', NULL, 1),
