(6456092, 958664, 133612, '<td valign="top">the contrast was a little washed out for me here, sorry.</td>', 'the contrast was a little washed out for me here, sorry.', '2011-06-29 19:01:46.000000', NULL, 1),
(6456116, 958563, 132996, '<td valign="top">Oh my gosh, so precious. His eyes are absolutely stunning and its amazing how you got his claws to be so strongly out! I also love the little tuft of white. :)</td>', 'Oh my gosh, so precious. His eyes are absolutely stunning and its amazing how you got his claws to be so strongly out! I also love the little tuft of white. :)', '2011-06-29 20:05:47.000000', NULL, 1),
(6456118, 959006, 132996, '<td valign="top">Intense. You lighted this perfectly. The shape is magnificent and captures the viewer instantly.</td>', 'Intense. You lighted this perfectly. The shape is magnificent and captures the viewer instantly.', '2011-06-29 20:08:00.000000', NULL, 1),
(6456132, 959296, 133277, '<td valign="top">lovely lighting.</td>', 'lovely lighting.', '2011-06-29 20:31:21.000000', NULL, 1),
(6456147, 959006, 43774, '<td valign="top">Nice!!</td>', 'Nice!!', '2011-06-29 21:06:42.000000', NULL, 1),
(6456164, 959281, 124815, '<td valign="top">This is so dark, at least on my screen, that I cannot see really anything. So I do not mark it.</td>', 'This is so dark, at least on my screen, that I cannot see really anything. So I do not mark it.', '2011-06-29 21:50:19.000000', NULL, 1),
(6456165, 959324, 65234, '<td valign="top">Beautiful!  I can see scales on the fish and ripples on the water''s surface, but the light in the water quickly dissipates into darkness.  Really cool use of low key.</td>', 'Beautiful!  I can see scales on the fish and ripples on the water''s surface, but the light in the water quickly dissipates into darkness.  Really cool use of low key.', '2011-06-29 21:50:23.000000', NULL, 1),
(6456167, 959201, 65234, '<td valign="top">Softly gorgeous.  Makes me feel like I stumbled on something really special in some vacation paradise.</td>', 'Softly gorgeous.  Makes me feel like I stumbled on something really special in some vacation paradise.', '2011-06-29 21:52:25.000000', NULL, 1),
(6456168, 959287, 65234, '<td valign="top">Lovely use of light.</td>', 'Lovely use of light.', '2011-06-29 21:52:57.000000', NULL, 1),
(6456170, 959065, 65234, '<td valign="top">Gorgeous pair; lighting shows just enough detail to engage me.</td>', 'Gorgeous pair; lighting shows just enough detail to engage me.', '2011-06-29 21:54:14.000000', NULL, 1),
(6456171, 959290, 65234, '<td valign="top">Lovely light to softly define the shape of the lilies and the vase.</td>', 'Lovely light to softly define the shape of the lilies and the vase.', '2011-06-29 21:55:26.000000', NULL, 1),
(6456174, 959164, 65234, '<td valign="top">Very moody in tone and pose.  That catchlight adds pathos.</td>', 'Very moody in tone and pose.  That catchlight adds pathos.', '2011-06-29 21:56:23.000000', NULL, 1),
(6456175, 958563, 65234, '<td valign="top">A prodigy at such a young age! Very cute pose and nicely lit for this challenge.</td>', 'A prodigy at such a young age! Very cute pose and nicely lit for this challenge.', '2011-06-29 21:57:26.000000', NULL, 1),
(6456177, 959006, 65234, '<td valign="top">Great use of that technique!  Possibly still a bit bright for a low key image, but still nice.</td>', 'Great use of that technique!  Possibly still a bit bright for a low key image, but still nice.', '2011-06-29 21:58:51.000000', NULL, 1),
(6456178, 959054, 65234, '<td valign="top">Feels like the storyteller worked late, and the child is already asleep.  Only the toy remains, waiting.</td>', 'Feels like the storyteller worked late, and the child is already asleep.  Only the toy remains, waiting.', '2011-06-29 21:59:40.000000', NULL, 1),
(6456182, 959285, 124815, '<td valign="top">Am wandering of the interest of this image in this medium (Lyrical abstraction). Hans Hartung had done with panache in the early 20th century this gestural abstract style and this is too much "in the manner of". I would prefer a drawing or painting to this photo. Therefore I do not mark it because in a photograph I expect a different feeling.</td>', 'Am wandering of the interest of this image in this medium (Lyrical abstraction). Hans Hartung had done with panache in the early 20th century this gestural abstract style and this is too much "in the manner of". I would prefer a drawing or painting to this photo. Therefore I do not mark it because in a photograph I expect a different feeling.', '2011-06-29 22:02:05.000000', NULL, 1),
(6456185, 958402, 124815, '<td valign="top">A solid image in the "constructivism" style.</td>', 'A solid image in the "constructivism" style.', '2011-06-29 22:03:27.000000', NULL, 1),
(6456187, 958596, 102315, '<td valign="top">I forsee a high placement. Beautifully done.</td>', 'I forsee a high placement. Beautifully done.', '2011-06-29 22:03:34.000000', NULL, 1),
(6456188, 958375, 124815, '<td valign="top">A classic.</td>', 'A classic.', '2011-06-29 22:03:45.000000', NULL, 1),
(6456189, 958904, 124815, '<td valign="top">Moonstruck. Good image.</td>', 'Moonstruck. Good image.', '2011-06-29 22:04:22.000000', NULL, 1),
(6456190, 959188, 124815, '<td valign="top">Another classic.</td>', 'Another classic.', '2011-06-29 22:05:26.000000', NULL, 1),
(6456191, 959010, 65234, '<td valign="top">Interesting choice of subject for this challenge.  You managed to make it low key, which, of course, you had to for this challenge, but it makes me think there should be something else out there that the sunflower is just barely illuminating ... or something that hints at why a normally bright and cheery flower isn''t.  If that makes sense ;-)</td>', 'Interesting choice of subject for this challenge.  You managed to make it low key, which, of course, you had to for this challenge, but it makes me think there should be something else out there that the sunflower is just barely illuminating ... or something that hints at why a normally bright and cheery flower isn''t.  If that makes sense ;-)', '2011-06-29 22:06:03.000000', NULL, 1),
(6456192, 958743, 124815, '<td valign="top">A good minimalist image.</td>', 'A good minimalist image.', '2011-06-29 22:06:25.000000', NULL, 1),
(6456194, 959058, 65234, '<td valign="top">Like the dark colors here but I find myself wanting something more in focus.</td>', 'Like the dark colors here but I find myself wanting something more in focus.', '2011-06-29 22:07:28.000000', NULL, 1),
(6456196, 958904, 65234, '<td valign="top">Lovely DOF and detail.  Not sure I would have left the flower yellow .. it''s such a bright and cheery color, and doesn''t really "feel" low key to me when I can see so much of it.</td>', 'Lovely DOF and detail.  Not sure I would have left the flower yellow .. it''s such a bright and cheery color, and doesn''t really "feel" low key to me when I can see so much of it.', '2011-06-29 22:10:21.000000', NULL, 1),
(6456197, 959273, 124815, '<td valign="top">Every line tells another worry. Dealing with unknowable present realities. Good portrait of a father.</td>', 'Every line tells another worry. Dealing with unknowable present realities. Good portrait of a father.', '2011-06-29 22:11:06.000000', NULL, 1),
(6456199, 959324, 124815, '<td valign="top">Hypnotic shot. Great title. <strike>9</strike> 10</td>', 'Hypnotic shot. Great title. 9 10', '2011-06-29 22:11:37.000000', NULL, 1),
(6456220, 959290, 124815, '<td valign="top">As if they are cast in bronze. Beautiful work. Great sadness. <strike>8</strike> 9</td>', 'As if they are cast in bronze. Beautiful work. Great sadness. 8 9', '2011-06-29 22:35:17.000000', NULL, 1),
